import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { PublicKey, Transaction, TransactionInstruction } from '@solana/web3.js';
import { TransactionBuilder } from '../../src/services/transaction.js';
import type { Config } from '../../src/config.js';

// Independent oracle from Rust 1f2b10a, not generated by the JavaScript SDK.
const fixture = JSON.parse(readFileSync(new URL('../fixtures/close_empty_token_accounts.json', import.meta.url), 'utf8'));
const wallet = new PublicKey(fixture.accounts[1].pubkey);
const builder = new TransactionBuilder({ priorityFee: 1000 } as Config);
const tokens = [4, 6].map(index => ({
  mintKey: fixture.accounts[index].pubkey,
  pubKey: fixture.accounts[index + 1].pubkey,
  programOwnerId: fixture.accounts[2].pubkey,
  amountUi: 0, isFrozen: false, lamports: 2_039_280,
}));

describe('MCP close-empty wire contract', () => {
  it.each([fixture.accounts[2].pubkey, 'TokenzQdBNbLqP5VEhdkAS6EPFLC1PHnBqCXEpPxuEb'])('uses the real SDK with Rust bytes and metas for %s', async program => {
    const plan = await builder.buildClaimPlan(tokens.map(t => ({ ...t, programOwnerId: program })), [], wallet, 10);
    const ix = plan.transactions[0].instructions[2];
    expect(ix.programId.toBase58()).toBe(fixture.programId);
    expect([...ix.data]).toEqual(fixture.data);
    expect(ix.keys.map(k => ({ ...k, pubkey: k.pubkey.toBase58() }))).toEqual(
      fixture.accounts.map((k: object, index: number) => index === 2 ? { ...k, pubkey: program } : k),
    );
    expect(() => builder.validateTransactions(plan.transactions, wallet)).not.toThrow();
  });

  it.each([{ data: [0] }, { data: [2, 0] }, { data: [3] }])('rejects legacy or unknown cleanup encoding $data before signing', async ({ data }) => {
    const plan = await builder.buildClaimPlan(tokens, [], wallet, 10);
    plan.transactions[0].instructions[2].data = Buffer.from(data);
    expect(() => builder.validateTransactions(plan.transactions, wallet)).toThrow('cleanup instruction');
  });

  it.each([8, 15])('rejects direct token burn discriminator %s', async discriminator => {
    const plan = await builder.buildClaimPlan(tokens, [], wallet, 10);
    for (const program of [fixture.accounts[2].pubkey, 'TokenzQdBNbLqP5VEhdkAS6EPFLC1PHnBqCXEpPxuEb']) {
      const tx = new Transaction().add(...plan.transactions[0].instructions, new TransactionInstruction({
        programId: new PublicKey(program), keys: [], data: Buffer.from([discriminator]),
      }));
      expect(() => builder.validateTransactions([tx], wallet)).toThrow('burn');
    }
  });

  it('keeps token programs separate and buffer selector 1 unchanged', async () => {
    const mixed = [tokens[0], { ...tokens[1], programOwnerId: 'TokenzQdBNbLqP5VEhdkAS6EPFLC1PHnBqCXEpPxuEb' }];
    const buffer = { pubkey: new PublicKey(new Uint8Array(32).fill(8)).toBase58(), lamports: 2_000_000 };
    const plan = await builder.buildClaimPlan(mixed, [buffer], wallet, 10);
    expect(plan.transactions.map(tx => [...tx.instructions[2].data])).toEqual([[2], [2], [1]]);
    expect(plan.transactions.slice(0, 2).map(tx => tx.instructions[2].keys[2].pubkey.toBase58())).toEqual(mixed.map(t => t.programOwnerId));
  });
});
